import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { assertAbsoluteIsoTimestamp, nextUpdatedTimestamp } from "../../db/timestamps";
import type { ApplicationTimelineEvent, Interview, Reminder } from "../../db/types";

export type CreateInterviewInput = Omit<Interview, "id" | "createdAt" | "updatedAt" | "status"> & { status?: Interview["status"] };
export type RescheduleInput = Pick<Interview, "startsAt" | "timezone"> & Partial<Pick<Interview, "endsAt">>;
export type UpdateInterviewInput = Partial<Omit<CreateInterviewInput, "status">>;

function validTimezone(value: string): boolean {
  try { new Intl.DateTimeFormat("en", { timeZone: value }).format(); return true; } catch { return false; }
}
function validateInput(input: CreateInterviewInput): void {
  assertAbsoluteIsoTimestamp(input.startsAt, "Interview.startsAt");
  if (input.endsAt !== undefined) {
    assertAbsoluteIsoTimestamp(input.endsAt, "Interview.endsAt");
    if (Date.parse(input.endsAt) <= Date.parse(input.startsAt)) throw new Error("Invalid Interview.endsAt");
  }
  if (!validTimezone(input.timezone)) throw new Error("Invalid Interview.timezone");
  if (!Number.isInteger(input.round) || input.round < 1) throw new Error("Invalid Interview.round");
  if (!Array.isArray(input.reminders)) throw new Error("Invalid Interview.reminders");
  for (const reminder of input.reminders) {
    if (!Number.isInteger(reminder.offsetMinutes) || reminder.offsetMinutes <= 0 || !["in-app", "browser"].includes(reminder.channel)) throw new Error("Invalid Interview.reminder");
  }
  if (input.status && !["scheduled", "completed", "cancelled", "rescheduled"].includes(input.status)) throw new Error("Invalid Interview.status");
}

export class InterviewService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;
  constructor(database: IDBDatabase, dependencies: { now?: () => string; createId?: () => string } = {}) {
    this.#database = database; this.#now = dependencies.now ?? (() => new Date().toISOString()); this.#createId = dependencies.createId ?? (() => crypto.randomUUID());
  }
  async createInterview(input: CreateInterviewInput): Promise<Interview> {
    validateInput(input);
    const timestamp = this.#now(); assertAbsoluteIsoTimestamp(timestamp, "Interview.createdAt");
    const interview: Interview = { ...input, id: this.#createId(), createdAt: timestamp, updatedAt: timestamp, status: input.status ?? "scheduled" };
    await runTransaction(this.#database, STORE_NAMES.interviews, "readwrite", tx => requestToPromise(tx.objectStore(STORE_NAMES.interviews).add(interview)));
    return interview;
  }
  create(input: CreateInterviewInput): Promise<Interview> { return this.createInterview(input); }
  get(id: string): Promise<Interview | undefined> { return this.getInterview(id); }
  list(applicationId?: string): Promise<Interview[]> { return this.listInterviews(applicationId); }
  getInterview(id: string): Promise<Interview | undefined> { return runTransaction(this.#database, STORE_NAMES.interviews, "readonly", tx => requestToPromise(tx.objectStore(STORE_NAMES.interviews).get(id))); }
  listInterviews(applicationId?: string): Promise<Interview[]> { return runTransaction(this.#database, STORE_NAMES.interviews, "readonly", async tx => { const store = tx.objectStore(STORE_NAMES.interviews); const records = applicationId === undefined ? await requestToPromise<Interview[]>(store.getAll()) : await requestToPromise<Interview[]>(store.index("applicationId").getAll(applicationId)); return records.sort((a,b)=>a.startsAt.localeCompare(b.startsAt)||a.round-b.round); }); }
  async updateInterview(id: string, patch: UpdateInterviewInput): Promise<Interview> {
    const current = await this.getInterview(id); if (!current) throw new Error(`Interview not found: ${id}`);
    validateInput({ ...current, ...patch });
    const timestamp = this.#now(); assertAbsoluteIsoTimestamp(timestamp, "Interview.updatedAt");
    const scheduleChanged = (patch.startsAt !== undefined && patch.startsAt !== current.startsAt) || (patch.endsAt !== undefined && patch.endsAt !== current.endsAt) || (patch.timezone !== undefined && patch.timezone !== current.timezone);
    const stores = scheduleChanged ? [STORE_NAMES.interviews, STORE_NAMES.applicationTimelineEvents] : [STORE_NAMES.interviews];
    return runTransaction(this.#database, stores, "readwrite", async tx => {
      const store = tx.objectStore(STORE_NAMES.interviews); const existing = await requestToPromise<Interview | undefined>(store.get(id)); if (!existing) throw new Error(`Interview not found: ${id}`);
      const updatedAt = nextUpdatedTimestamp(timestamp, existing.updatedAt); const updated: Interview = { ...existing, ...patch, ...(scheduleChanged ? { status: "rescheduled" as const } : {}), id: existing.id, createdAt: existing.createdAt, updatedAt };
      await requestToPromise(store.put(updated));
      if (scheduleChanged) { const event: ApplicationTimelineEvent = { id: this.#createId(), createdAt: updatedAt, updatedAt, applicationId: existing.applicationId, type: "interview-rescheduled", fromValue: JSON.stringify({ startsAt: existing.startsAt, endsAt: existing.endsAt, timezone: existing.timezone }), toValue: JSON.stringify({ startsAt: updated.startsAt, endsAt: updated.endsAt, timezone: updated.timezone }), note: "Interview rescheduled." }; await requestToPromise(tx.objectStore(STORE_NAMES.applicationTimelineEvents).add(event)); }
      return updated;
    });
  }
  update(id: string, patch: UpdateInterviewInput): Promise<Interview> { return this.updateInterview(id, patch); }
  async rescheduleInterview(id: string, input: RescheduleInput): Promise<Interview> {
    const current = await this.getInterview(id); if (!current) throw new Error(`Interview not found: ${id}`);
    validateInput({ ...current, ...input });
    const candidate = this.#now(); assertAbsoluteIsoTimestamp(candidate, "Interview.updatedAt");
    return runTransaction(this.#database, [STORE_NAMES.interviews, STORE_NAMES.applicationTimelineEvents], "readwrite", async tx => {
      const store = tx.objectStore(STORE_NAMES.interviews);
      const existing = await requestToPromise<Interview | undefined>(store.get(id)); if (!existing) throw new Error(`Interview not found: ${id}`);
      const updatedAt = nextUpdatedTimestamp(candidate, existing.updatedAt);
      const updated = { ...existing, ...input, status: "rescheduled" as const, updatedAt };
      await requestToPromise(store.put(updated));
      const event: ApplicationTimelineEvent = { id: this.#createId(), createdAt: updatedAt, updatedAt, applicationId: existing.applicationId, type: "interview-rescheduled", fromValue: JSON.stringify({ startsAt: existing.startsAt, endsAt: existing.endsAt, timezone: existing.timezone }), toValue: JSON.stringify({ startsAt: updated.startsAt, endsAt: updated.endsAt, timezone: updated.timezone }), note: "Interview rescheduled." };
      await requestToPromise(tx.objectStore(STORE_NAMES.applicationTimelineEvents).add(event));
      return updated;
    });
  }
  reschedule(id: string, input: RescheduleInput): Promise<Interview> { return this.rescheduleInterview(id, input); }
  async setStatus(id: string, status: "cancelled" | "completed"): Promise<Interview> {
    const current = await this.getInterview(id); if (!current) throw new Error(`Interview not found: ${id}`);
    const timestamp = this.#now(); assertAbsoluteIsoTimestamp(timestamp, "Interview.updatedAt");
    return runTransaction(this.#database, STORE_NAMES.interviews, "readwrite", async tx => {
      const existing = await requestToPromise<Interview | undefined>(tx.objectStore(STORE_NAMES.interviews).get(id)); if (!existing) throw new Error(`Interview not found: ${id}`);
      const updated = { ...existing, status, updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) }; await requestToPromise(tx.objectStore(STORE_NAMES.interviews).put(updated)); return updated;
    });
  }
  cancelInterview(id: string): Promise<Interview> { return this.setStatus(id, "cancelled"); }
  completeInterview(id: string): Promise<Interview> { return this.setStatus(id, "completed"); }
  async listTimeline(applicationId: string): Promise<ApplicationTimelineEvent[]> { return runTransaction(this.#database, STORE_NAMES.applicationTimelineEvents, "readonly", async tx => (await requestToPromise<ApplicationTimelineEvent[]>(tx.objectStore(STORE_NAMES.applicationTimelineEvents).index("applicationId").getAll(applicationId))).sort((a,b)=>a.createdAt.localeCompare(b.createdAt))); }
}

export type { Reminder };
import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { assertAbsoluteIsoTimestamp, nextUpdatedTimestamp } from "../../db/timestamps";
import type { InterviewReview } from "../../db/types";

export type InterviewReviewInput = Omit<InterviewReview, "id" | "createdAt" | "updatedAt" | "interviewId">;

export class InterviewReviewService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;
  constructor(database: IDBDatabase, dependencies: { now?: () => string; createId?: () => string } = {}) {
    this.#database = database; this.#now = dependencies.now ?? (() => new Date().toISOString()); this.#createId = dependencies.createId ?? (() => crypto.randomUUID());
  }
  async saveReview(interviewId: string, input: InterviewReviewInput): Promise<InterviewReview> {
    if (input.overallRating !== undefined && (!Number.isFinite(input.overallRating) || input.overallRating < 0 || input.overallRating > 5)) throw new Error("Invalid InterviewReview.overallRating");
    const timestamp = this.#now(); assertAbsoluteIsoTimestamp(timestamp, "InterviewReview.createdAt");
    return runTransaction(this.#database, STORE_NAMES.interviewReviews, "readwrite", async tx => {
      const store = tx.objectStore(STORE_NAMES.interviewReviews);
      const existing = await requestToPromise<InterviewReview | undefined>(store.index("interviewId").get(interviewId));
      const review: InterviewReview = existing ? { ...existing, ...input, id: existing.id, interviewId, updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) } : { ...input, id: this.#createId(), interviewId, createdAt: timestamp, updatedAt: timestamp };
      await requestToPromise(store.put(review)); return review;
    });
  }
  save(interviewId: string, input: InterviewReviewInput): Promise<InterviewReview> { return this.saveReview(interviewId, input); }
  createOrUpdate(interviewId: string, input: InterviewReviewInput): Promise<InterviewReview> { return this.saveReview(interviewId, input); }
  getReview(interviewId: string): Promise<InterviewReview | undefined> { return runTransaction(this.#database, STORE_NAMES.interviewReviews, "readonly", tx => requestToPromise(tx.objectStore(STORE_NAMES.interviewReviews).index("interviewId").get(interviewId))); }
}
import type { ResumeIngestionService } from "../features/resumes/ingestion";
import { createApplicationBoard } from "../components/ApplicationBoard/ApplicationBoard";
import { createInterviewCalendar } from "../components/InterviewCalendar/InterviewCalendar";
import { createInterviewReview } from "../components/InterviewReview/InterviewReview";
import type { MatchingService } from "../features/matching/matchingService";
import type { ApplicationBoardOptions } from "../components/ApplicationBoard/ApplicationBoard";

export interface ResumeLibraryUiService {
  search(query?: string): Promise<any[]>;
  getResumeText(resumeId: string, kind?: "extracted" | "confirmed" | "manual"): Promise<any>;
  getDownloadData(resumeId: string): Promise<{ blob: Blob; fileName: string }>;
  exportConfirmedText(resumeId: string): Promise<Blob>;
  getResume(resumeId: string): Promise<any>;
  updateMetadata(resumeId: string, patch: { name?: string; tags?: string[] }): Promise<any>;
  previewDelete(resumeId: string): Promise<any>;
  deleteResume(resumeId: string, options?: { confirmed?: boolean }): Promise<void>;
  confirmText(resumeId: string, text: string): Promise<any>;
}

export interface CreateAppOptions {
  resumeLibrary?: any;
  resumeIngestion?: ResumeIngestionService;
  applicationService?: ApplicationBoardOptions["applicationService"];
  stageService?: ApplicationBoardOptions["stageService"];
  jobDescriptionService?: ApplicationBoardOptions["jobDescriptionService"];
  matchingService?: MatchingService;
  aiAdvisorService?: ApplicationBoardOptions["aiAdvisorService"];
  interviewService?: any;
  reviewService?: any;
  notificationService?: any;
  exportInterviewICS?: (id: string) => Promise<string>;
}

export function createApp(
  documentRef: Document,
  options: CreateAppOptions = {},
): HTMLElement {
  const root = documentRef.getElementById("app");

  if (!root) {
    throw new Error("找不到应用挂载节点 #app");
  }

  root.innerHTML = `
    <div class="app-shell">
      <header class="topbar">
        <div class="brand" aria-label="求职工作台">
          <span class="brand-mark" aria-hidden="true">职</span>
          <span>求职工作台</span>
        </div>
        <div class="local-status" role="status" aria-live="polite">
          <span class="status-dot" aria-hidden="true"></span>
          本地数据已就绪
        </div>
      </header>

      <main>
        <section class="overview" aria-labelledby="page-title">
          <p class="section-label">概览</p>
          <div class="overview-heading">
            <h1 id="page-title">求职工作台</h1>
            <p>数据仅保存在此浏览器</p>
          </div>

          <dl class="summary-grid" aria-label="本地资料概览">
            <div class="summary-item">
              <dt>简历</dt>
              <dd class="resume-summary-count">0 份简历</dd>
            </div>
            <div class="summary-item">
              <dt>职位</dt>
              <dd>0 个职位</dd>
            </div>
            <div class="summary-item summary-item--accent">
              <dt>近期面试</dt>
              <dd>暂无安排</dd>
            </div>
          </dl>
        </section>

        <section class="resume-library" aria-labelledby="resume-library-title">
          <div class="section-heading">
            <div>
              <p class="section-label">资料</p>
              <h2 id="resume-library-title">简历版本库</h2>
            </div>
            <label class="resume-upload-button">
              <span>上传简历</span>
              <input class="resume-file-input" type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" />
            </label>
          </div>
          <div class="resume-library-toolbar">
            <label for="resume-search">搜索简历</label>
            <input id="resume-search" type="search" placeholder="按名称、文件名或标签搜索" autocomplete="off" />
            <button type="button" class="resume-refresh" aria-label="刷新简历列表">刷新</button>
          </div>
          <div class="resume-library-status" role="status" aria-live="polite" aria-atomic="true">暂无简历版本</div>
          <div class="resume-library-list" aria-live="polite"></div>
          <div class="resume-editor" hidden>
            <label for="resume-text-editor">确认简历文本</label>
            <textarea id="resume-text-editor" rows="12"></textarea>
            <div class="resume-editor__actions">
              <button type="button" data-action="confirm-text">确认文本</button>
              <button type="button" data-action="cancel-text">取消</button>
            </div>
          </div>
          <div class="resume-metadata-editor" hidden>
            <h3>编辑版本信息</h3>
            <label for="resume-name-editor">版本名称</label>
            <input id="resume-name-editor" type="text" />
            <label for="resume-tags-editor">标签（用逗号分隔）</label>
            <input id="resume-tags-editor" type="text" />
            <div class="resume-editor__actions">
              <button type="button" data-action="save-metadata">保存</button>
              <button type="button" data-action="cancel-metadata">取消</button>
            </div>
          </div>
          <div class="resume-delete-preview" role="dialog" aria-modal="true" aria-labelledby="resume-delete-title" hidden>
            <h3 id="resume-delete-title">确认删除简历</h3>
            <p class="resume-delete-summary"></p>
            <div class="resume-editor__actions">
              <button type="button" data-action="confirm-delete">确认删除</button>
              <button type="button" data-action="cancel-delete">取消</button>
            </div>
          </div>
        </section>

        <section class="today" aria-labelledby="today-title">
          <div class="section-heading">
            <div>
              <p class="section-label">今天</p>
              <h2 id="today-title">待处理事项</h2>
            </div>
            <span class="count" aria-label="0 项">0</span>
          </div>
          <div class="empty-state">
            <span class="empty-line" aria-hidden="true"></span>
            <p>今天没有待处理事项</p>
          </div>
        </section>
        <div class="application-board-mount"></div>
        <div class="interview-calendar-mount"></div>
        <div class="interview-review-mount"></div>
      </main>
    </div>
  `;

  const applicationMount = root.querySelector<HTMLElement>(".application-board-mount");
  if (applicationMount) {
    applicationMount.replaceWith(createApplicationBoard(documentRef, {
      applicationService: options.applicationService,
      stageService: options.stageService,
      jobDescriptionService: options.jobDescriptionService,
      resumeLibrary: options.resumeLibrary,
      matchingService: options.matchingService,
      aiAdvisorService: options.aiAdvisorService,
    }));
  }

  const interviewMount = root.querySelector<HTMLElement>(".interview-calendar-mount");
  if (interviewMount) {
    interviewMount.replaceWith(createInterviewCalendar(documentRef, {
      interviewService: options.interviewService,
      applications: async () => options.applicationService?.listApplications?.() ?? [],
      notificationService: options.notificationService,
      exportInterviewICS: options.exportInterviewICS,
    }));
  }
  const reviewMount = root.querySelector<HTMLElement>(".interview-review-mount");
  if (reviewMount) {
    const review = createInterviewReview(documentRef, { reviewService: options.reviewService });
    reviewMount.replaceWith(review);
    root.querySelector("[data-component=interview-calendar]")?.addEventListener("interview-selected", (event) => {
      review.dispatchEvent(new CustomEvent("interview-selected", { detail: (event as CustomEvent<string>).detail }));
    });
  }

  const status = root.querySelector<HTMLElement>(".resume-library-status");
  const resumeSummary = root.querySelector<HTMLElement>(".resume-summary-count");
  const list = root.querySelector<HTMLElement>(".resume-library-list");
  const search = root.querySelector<HTMLInputElement>("#resume-search");
  const fileInput = root.querySelector<HTMLInputElement>(".resume-file-input");
  const refresh = root.querySelector<HTMLButtonElement>(".resume-refresh");
  const editor = root.querySelector<HTMLElement>(".resume-editor");
  const editorText = root.querySelector<HTMLTextAreaElement>("#resume-text-editor");
  const metadataEditor = root.querySelector<HTMLElement>(".resume-metadata-editor");
  const nameEditor = root.querySelector<HTMLInputElement>("#resume-name-editor");
  const tagsEditor = root.querySelector<HTMLInputElement>("#resume-tags-editor");
  const deletePreview = root.querySelector<HTMLElement>(".resume-delete-preview");
  const deleteSummary = root.querySelector<HTMLElement>(".resume-delete-summary");
  let editingResumeId: string | undefined;
  let metadataResumeId: string | undefined;
  let pendingDeleteId: string | undefined;

  const render = async (query = "") => {
    if (!list) return;
    const resumes = options.resumeLibrary ? await options.resumeLibrary.search(query) : [];
    list.innerHTML = resumes.length
      ? resumes.map((resume: any) => `
          <article class="resume-library-item" data-resume-id="${resume.id}">
            <div class="resume-library-item__body">
              <h3 title="${escapeHtml(resume.name)}">${escapeHtml(resume.name)}</h3>
              <p>${escapeHtml(resume.fileName)}</p>
              <p class="resume-library-item__meta">${escapeHtml(resume.status)}${resume.tags.length ? ` · ${escapeHtml(resume.tags.join("、"))}` : ""}</p>
            </div>
            <div class="resume-library-item__actions">
              <button type="button" data-action="preview" data-resume-id="${resume.id}">预览文本</button>
              <button type="button" data-action="edit-metadata" data-resume-id="${resume.id}">编辑名称和标签</button>
              ${resume.status === "extraction-failed" ? `<button type="button" data-action="retry" data-resume-id="${resume.id}">重试提取</button>` : ""}
              <button type="button" data-action="export" data-resume-id="${resume.id}">导出文本</button>
              <button type="button" data-action="download" data-resume-id="${resume.id}">下载原文件</button>
              <button type="button" data-action="delete" data-resume-id="${resume.id}">删除</button>
            </div>
          </article>
        `).join("")
      : "";
    if (status) status.textContent = resumes.length ? `${resumes.length} 个简历版本` : "暂无简历版本";
    if (resumeSummary) resumeSummary.textContent = `${resumes.length} 份简历`;
  };

  search?.addEventListener("input", () => void render(search.value));
  refresh?.addEventListener("click", () => void render(search?.value ?? ""));
  fileInput?.addEventListener("change", async () => {
    const file = fileInput.files?.[0];
    if (!file || !options.resumeIngestion) return;
    try {
      const result = await options.resumeIngestion.ingest(file);
      if (status) status.textContent = result.outcome === "needs-review" ? "提取完成，请确认文本" : "提取失败，请粘贴或校正文本";
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "简历保存失败";
    }
    fileInput.value = "";
  });

  list?.addEventListener("click", async (event) => {
    const target = event.target as HTMLElement;
    const button = target.closest<HTMLButtonElement>("button[data-action]");
    const resumeId = button?.dataset.resumeId;
    if (!button || !resumeId || !options.resumeLibrary) return;
    try {
      if (button.dataset.action === "preview") {
        const textRecord = await options.resumeLibrary.getResumeText(resumeId, "confirmed")
          ?? await options.resumeLibrary.getResumeText(resumeId, "extracted")
          ?? await options.resumeLibrary.getResumeText(resumeId, "manual");
        editingResumeId = resumeId;
        if (editorText) editorText.value = textRecord?.text ?? "";
        if (editor) editor.hidden = false;
        if (status) status.textContent = textRecord ? `已读取文本（${textRecord.text.length} 字）` : "尚未提取文本，请粘贴或校正";
      } else if (button.dataset.action === "download") {
        const download = await options.resumeLibrary.getDownloadData(resumeId);
        triggerDownload(documentRef, download.blob, download.fileName);
        if (status) status.textContent = "原文件已下载";
      } else if (button.dataset.action === "export") {
        const blob = await options.resumeLibrary.exportConfirmedText(resumeId);
        triggerDownload(documentRef, blob, "resume-confirmed.txt");
        if (status) status.textContent = "确认文本已导出";
      } else if (button.dataset.action === "edit-metadata") {
        const resume = await options.resumeLibrary.getResume(resumeId);
        if (!resume) throw new Error("简历版本不存在");
        metadataResumeId = resumeId;
        if (nameEditor) nameEditor.value = resume.name;
        if (tagsEditor) tagsEditor.value = resume.tags.join(", ");
        if (metadataEditor) metadataEditor.hidden = false;
      } else if (button.dataset.action === "retry") {
        if (!options.resumeIngestion) throw new Error("当前无法重试文本提取");
        const result = await options.resumeIngestion.retryExtraction(resumeId);
        if (status) status.textContent = result.outcome === "needs-review" ? "重新提取完成，请确认文本" : "提取仍然失败，可继续手动粘贴文本";
        await render(search?.value ?? "");
      } else if (button.dataset.action === "delete") {
        const preview = await options.resumeLibrary.previewDelete(resumeId);
        pendingDeleteId = resumeId;
        if (deleteSummary) deleteSummary.textContent = `将删除“${preview.name}”及其原文件；已固化的使用历史不会删除。`;
        if (deletePreview) deletePreview.hidden = false;
        if (status) status.textContent = "删除预览已打开，尚未删除任何数据";
      }
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "操作失败";
    }
  });

  metadataEditor?.addEventListener("click", async (event) => {
    const action = (event.target as HTMLElement).closest<HTMLButtonElement>("button[data-action]")?.dataset.action;
    if (action === "cancel-metadata") {
      metadataEditor.hidden = true;
      metadataResumeId = undefined;
      return;
    }
    if (action !== "save-metadata" || !metadataResumeId || !options.resumeLibrary) return;
    try {
      await options.resumeLibrary.updateMetadata(metadataResumeId, {
        name: nameEditor?.value,
        tags: tagsEditor?.value.split(/[,，]/),
      });
      metadataEditor.hidden = true;
      if (status) status.textContent = "版本名称和标签已保存";
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "版本信息保存失败";
    }
  });

  deletePreview?.addEventListener("click", async (event) => {
    const action = (event.target as HTMLElement).closest<HTMLButtonElement>("button[data-action]")?.dataset.action;
    if (action === "cancel-delete") {
      deletePreview.hidden = true;
      pendingDeleteId = undefined;
      if (status) status.textContent = "已取消删除，数据未改变";
      return;
    }
    if (action !== "confirm-delete" || !pendingDeleteId || !options.resumeLibrary) return;
    try {
      await options.resumeLibrary.deleteResume(pendingDeleteId, { confirmed: true });
      deletePreview.hidden = true;
      pendingDeleteId = undefined;
      if (status) status.textContent = "简历已删除";
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "删除失败";
    }

