:root {
  color: #202522;
  background: #f3f4ef;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    linear-gradient(#d9ddd4 1px, transparent 1px),
    #f3f4ef;
  background-size: 100% 48px;
}

button,
a,
input,
textarea,
select {
  font: inherit;
}

:focus-visible {
  outline: 3px solid #1d6b4d;
  outline-offset: 3px;
}

.app-shell {
  width: min(100% - 32px, 1120px);
  margin: 0 auto;
  padding-bottom: 56px;
}

.topbar {
  display: flex;
  min-height: 72px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid #c9cec4;
}

.brand {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  color: #1c211e;
  font-size: 15px;
  font-weight: 700;
}

.brand-mark {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 7px;
  color: #fff;
  background: #1d513d;
  font-size: 15px;
}

.local-status {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  color: #4d554f;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.status-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #25845d;
  box-shadow: 0 0 0 3px #d9e8de;
}

main {
  display: grid;
  gap: 52px;
  padding-top: 64px;
}

.section-label {
  margin: 0 0 10px;
  color: #687069;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

.overview-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
}

h1,
h2,
p,
dl,
dd {
  margin-top: 0;
}

h1 {
  max-width: 100%;
  margin-bottom: 0;
  color: #1b201d;
  font-size: 38px;
  line-height: 1.16;
  letter-spacing: 0;
  overflow-wrap: anywhere;
}

.overview-heading p {
  margin-bottom: 5px;
  color: #687069;
  font-size: 14px;
  text-align: right;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  margin: 36px 0 0;
  border: 1px solid #ccd1c8;
  border-radius: 8px;
  overflow: hidden;
  background: #ccd1c8;
}

.summary-item {
  min-height: 132px;
  padding: 24px;
  background: #fff;
}

.summary-item--accent {
  border-top: 3px solid #b35c35;
  padding-top: 21px;
}

.summary-item dt {
  margin-bottom: 26px;
  color: #687069;
  font-size: 13px;
}

.summary-item dd {
  margin-bottom: 0;
  color: #222824;
  font-size: 22px;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.today {
  border-top: 1px solid #c9cec4;
  padding-top: 24px;
}

.section-heading {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 20px;
}

h2 {
  margin-bottom: 0;
  font-size: 21px;
  line-height: 1.3;
  letter-spacing: 0;
}

.count {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid #bcc3b9;
  border-radius: 50%;
  color: #59615a;
  background: #f9faf7;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.empty-state {
  display: flex;
  min-height: 136px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 20px;
  border: 1px dashed #b8beb5;
  border-radius: 8px;
  color: #687069;
  background: rgb(255 255 255 / 58%);
}

.empty-state p {
  margin-bottom: 0;
  overflow-wrap: anywhere;
}

.empty-line {
  width: 24px;
  height: 2px;
  background: #b35c35;
}

.resume-library {
  border-top: 1px solid #c9cec4;
  padding-top: 24px;
}

.resume-upload-button {
