import { requestToPromise, runTransaction } from "../db/database";
import { STORE_NAMES } from "../db/schema";
import { calculateReminderTime } from "./reminders";
import type { Interview, ReminderFailure } from "../db/types";

export interface NotificationResult { reminderAt: string; browserScheduled: boolean; inAppReminder: { interviewId: string; reminderAt: string }; failure?: ReminderFailure; }
export async function scheduleReminder(database: IDBDatabase, interview: Interview, reminder: Interview["reminders"][number], options: { now?: () => string; NotificationCtor?: typeof Notification } = {}): Promise<NotificationResult> {
  const reminderAt = calculateReminderTime(interview.startsAt, reminder);
  const now = options.now ?? (() => new Date().toISOString());
  const Ctor = options.NotificationCtor ?? (typeof Notification !== "undefined" ? Notification : undefined);
  let browserScheduled = false; let reason: string | undefined;
  if (reminder.channel === "browser") {
    try {
      if (!Ctor) reason = "notifications-unavailable";
      else if (Ctor.permission !== "granted") reason = `permission-${Ctor.permission}`;
      else { new Ctor(interview.title); browserScheduled = true; }
    } catch (error) { reason = error instanceof Error ? error.name : "notification-failed"; }
  }
  let failure: ReminderFailure | undefined;
  if (reason) {
    const timestamp = now();
    failure = { id: crypto.randomUUID(), createdAt: timestamp, updatedAt: timestamp, interviewId: interview.id, reminderAt, reason };
    await runTransaction(database, STORE_NAMES.reminderFailures, "readwrite", tx => requestToPromise(tx.objectStore(STORE_NAMES.reminderFailures).add(failure)));
  }
  return { reminderAt, browserScheduled, inAppReminder: { interviewId: interview.id, reminderAt }, ...(failure ? { failure } : {}) };
}

export class NotificationService {
  readonly #database: IDBDatabase;
  readonly #options: { now?: () => string; NotificationCtor?: typeof Notification };
  constructor(database: IDBDatabase, options: { now?: () => string; NotificationCtor?: typeof Notification } = {}) { this.#database = database; this.#options = options; }
  schedule(interview: Interview, reminder: Interview["reminders"][number]): Promise<NotificationResult> { return scheduleReminder(this.#database, interview, reminder, this.#options); }
  scheduleReminder(interview: Interview, reminder: Interview["reminders"][number]): Promise<NotificationResult> { return this.schedule(interview, reminder); }
}

export async function scheduleInterviewReminders(database: IDBDatabase, interview: Interview, options: { now?: () => string; NotificationCtor?: typeof Notification } = {}): Promise<NotificationResult[]> {
  return Promise.all(interview.reminders.map((reminder) => scheduleReminder(database, interview, reminder, options)));
}
import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { assertAbsoluteIsoTimestamp, nextUpdatedTimestamp } from "../../db/timestamps";
import type { InterviewReview } from "../../db/types";

export type InterviewReviewInput = Omit<InterviewReview, "id" | "createdAt" | "updatedAt" | "interviewId">;

export class InterviewReviewService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;
  constructor(database: IDBDatabase, dependencies: { now?: () => string; createId?: () => string } = {}) {
    this.#database = database; this.#now = dependencies.now ?? (() => new Date().toISOString()); this.#createId = dependencies.createId ?? (() => crypto.randomUUID());
  }
  async saveReview(interviewId: string, input: InterviewReviewInput): Promise<InterviewReview> {
    if (input.overallRating !== undefined && (!Number.isFinite(input.overallRating) || input.overallRating < 0 || input.overallRating > 5)) throw new Error("Invalid InterviewReview.overallRating");
    const timestamp = this.#now(); assertAbsoluteIsoTimestamp(timestamp, "InterviewReview.createdAt");
    return runTransaction(this.#database, STORE_NAMES.interviewReviews, "readwrite", async tx => {
      const store = tx.objectStore(STORE_NAMES.interviewReviews);
      const existing = await requestToPromise<InterviewReview | undefined>(store.index("interviewId").get(interviewId));
      const review: InterviewReview = existing ? { ...existing, ...input, id: existing.id, interviewId, updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) } : { ...input, id: this.#createId(), interviewId, createdAt: timestamp, updatedAt: timestamp };
      await requestToPromise(store.put(review)); return review;
    });
  }
  save(interviewId: string, input: InterviewReviewInput): Promise<InterviewReview> { return this.saveReview(interviewId, input); }
  createOrUpdate(interviewId: string, input: InterviewReviewInput): Promise<InterviewReview> { return this.saveReview(interviewId, input); }
  getReview(interviewId: string): Promise<InterviewReview | undefined> { return runTransaction(this.#database, STORE_NAMES.interviewReviews, "readonly", tx => requestToPromise(tx.objectStore(STORE_NAMES.interviewReviews).index("interviewId").get(interviewId))); }
}
import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { nextUpdatedTimestamp } from "../../db/timestamps";
import type {
  Resume,
  ResumeText,
  ResumeUsageHistory,
  StoredFile,
} from "../../db/types";
import type { ResumeDownloadData } from "./ingestion";

export interface ResumeLibraryDependencies {
  now?: () => string;
  createId?: () => string;
}

export interface ResumeDeletePreview {
  id: string;
  name: string;
  fileName: string;
  fileSize: number;
  status: Resume["status"];
  hasOriginalFile: boolean;
  confirmedTextLength: number;
}

export interface ResumeConfirmResult {
  resume: Resume;
  text: ResumeText;
}

export interface ResumeMetadataPatch {
  name?: string;
  tags?: string[];
}

function defaultNow(): string {
  return new Date().toISOString();
}

function defaultCreateId(): string {
  return crypto.randomUUID();
}

function normalizeTags(tags: string[] | undefined): string[] | undefined {
  if (!tags) return undefined;
  return [...new Set(tags.map((tag) => tag.trim()).filter(Boolean))];
}

export class ResumeLibraryService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;

  constructor(database: IDBDatabase, dependencies: ResumeLibraryDependencies = {}) {
    this.#database = database;
    this.#now = dependencies.now ?? defaultNow;
    this.#createId = dependencies.createId ?? defaultCreateId;
  }

  async getResume(resumeId: string): Promise<Resume | undefined> {
    return runTransaction(this.#database, STORE_NAMES.resumes, "readonly", (tx) =>
      requestToPromise<Resume | undefined>(tx.objectStore(STORE_NAMES.resumes).get(resumeId)),
    );
  }

  async listResumes(query = ""): Promise<Resume[]> {
    const resumes = await runTransaction(this.#database, STORE_NAMES.resumes, "readonly", (tx) =>
      requestToPromise<Resume[]>(tx.objectStore(STORE_NAMES.resumes).getAll()),
    );
    const needle = query.trim().toLocaleLowerCase();
    return resumes
      .filter((resume) => {
        if (!needle) return true;
        return [resume.name, resume.fileName, ...resume.tags]
          .some((value) => value.toLocaleLowerCase().includes(needle));
      })
      .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  }

  search(query = ""): Promise<Resume[]> {
    return this.listResumes(query);
  }

  list(query = ""): Promise<Resume[]> {
    return this.listResumes(query);
  }

  async getText(resumeId: string, kind: ResumeText["kind"]): Promise<ResumeText | undefined> {
    return runTransaction(this.#database, STORE_NAMES.resumeTexts, "readonly", (tx) =>
      requestToPromise<ResumeText | undefined>(
        tx.objectStore(STORE_NAMES.resumeTexts).index("resumeId_kind").get([resumeId, kind]),
      ),
    );
  }

  async getConfirmedTextRecord(resumeId: string): Promise<ResumeText | undefined> {
    const resume = await this.getResume(resumeId);
    if (resume?.textSource === "manual") return this.getText(resumeId, "manual");
    if (resume?.textSource === "extracted") return this.getText(resumeId, "confirmed");
    const manual = await this.getText(resumeId, "manual");
    const confirmed = await this.getText(resumeId, "confirmed");
    if (!manual) return confirmed;
    if (!confirmed) return manual;
    return manual.updatedAt >= confirmed.updatedAt ? manual : confirmed;
  }

  async getConfirmedText(resumeId: string): Promise<string | undefined> {
    return (await this.getConfirmedTextRecord(resumeId))?.text;
  }

  getResumeText(resumeId: string, kind: ResumeText["kind"] = "confirmed"): Promise<ResumeText | undefined> {
    return kind === "confirmed" ? this.getConfirmedTextRecord(resumeId) : this.getText(resumeId, kind);
  }

  async confirmText(resumeId: string, text: string): Promise<ResumeConfirmResult> {
    const value = text;
    if (!value.trim()) throw new Error("Confirmed resume text cannot be empty.");
    const timestamp = this.#now();
    const result = await runTransaction(
      this.#database,
      [STORE_NAMES.resumes, STORE_NAMES.resumeTexts],
      "readwrite",
      async (tx) => {
        const resumeStore = tx.objectStore(STORE_NAMES.resumes);
        const textStore = tx.objectStore(STORE_NAMES.resumeTexts);
        const resume = await requestToPromise<Resume | undefined>(resumeStore.get(resumeId));
        if (!resume) throw new Error(`Resume not found: ${resumeId}`);
        const extracted = await requestToPromise<ResumeText | undefined>(
          textStore.index("resumeId_kind").get([resumeId, "extracted"]),
        );
        const kind: ResumeText["kind"] = extracted?.text === value ? "confirmed" : "manual";
        const existing = await requestToPromise<ResumeText | undefined>(
          textStore.index("resumeId_kind").get([resumeId, kind]),
        );
        const textRecord: ResumeText = existing
          ? { ...existing, text: value, confirmedAt: timestamp, updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) }
          : {
              id: this.#createId(),
              createdAt: timestamp,
              updatedAt: timestamp,
              resumeId,
              kind,
              text: value,
              confirmedAt: timestamp,
            };
        if (existing) await requestToPromise(textStore.put(textRecord));
        else await requestToPromise(textStore.add(textRecord));
        const updatedResume: Resume = {
          ...resume,
          status: "ready",
          textSource: kind === "confirmed" ? "extracted" : "manual",
          textConfirmedAt: timestamp,
          updatedAt: nextUpdatedTimestamp(timestamp, resume.updatedAt),
        };
        await requestToPromise(resumeStore.put(updatedResume));
        return { resume: updatedResume, text: textRecord };
      },
    );
    return result;
  }

  updateText(resumeId: string, text: string): Promise<ResumeConfirmResult> {
    return this.confirmText(resumeId, text);
  }

  async updateMetadata(resumeId: string, patch: ResumeMetadataPatch): Promise<Resume> {
    return runTransaction(this.#database, STORE_NAMES.resumes, "readwrite", async (tx) => {
      const store = tx.objectStore(STORE_NAMES.resumes);
      const resume = await requestToPromise<Resume | undefined>(store.get(resumeId));
      if (!resume) throw new Error(`Resume not found: ${resumeId}`);
      const updated: Resume = {
        ...resume,
